function Invoke-ProfileNvidPostFailureRecovery {
    param([Parameter(Mandatory=$true)]$ErrorRecord)
    $message = [string]$ErrorRecord.Exception.Message
    if ($message -notmatch 'NVIDIA Control Panel launch failed|NVIDIA Control Panel is not visibly open|Timed out waiting for window') { return $false }
    Write-Host ("  Recovering from NVIDIA UI launch verification failure: {0}" -f $message) -ForegroundColor DarkYellow
    $appExe = 'C:\Program Files\NVIDIA Corporation\NVIDIA App\CEF\NVIDIA App.exe'
    if (-not (Test-Path -LiteralPath $appExe -PathType Leaf)) { return $false }
    try { Start-Process -FilePath $appExe -WorkingDirectory (Split-Path -Parent $appExe) | Out-Null } catch {}
    $appWindow = Wait-NvidWindow -TitlePattern @('NVIDIA*') -ProcessNames @('NVIDIA App') -ExcludeTitlePattern @('*Control Panel*') -TimeoutSeconds 60
    $cplPackage = Get-AppxPackage -Name 'NVIDIACorp.NVIDIAControlPanel' -ErrorAction SilentlyContinue | Select-Object -First 1
    $cplWindow = Wait-NvidWindow -TitlePattern @('*NVIDIA Control Panel*','NVIDIA*') -ProcessNames @('nvcplui','vcplui','ApplicationFrameHost') -TimeoutSeconds 4
    if (-not $cplWindow -and $cplPackage -and $cplPackage.InstallLocation) {
        foreach ($candidateName in @('nvcplui.exe','vcplui.exe')) {
            $candidatePath = Join-Path $cplPackage.InstallLocation $candidateName
            if (Test-Path -LiteralPath $candidatePath -PathType Leaf) {
                try { Start-Process -FilePath $candidatePath | Out-Null } catch {}
                $cplWindow = Wait-NvidWindow -TitlePattern @('*NVIDIA Control Panel*','NVIDIA*') -ProcessNames @('nvcplui','vcplui','ApplicationFrameHost') -TimeoutSeconds 90
                if ($cplWindow) { break }
            }
        }
    }
    $driver = Get-CimInstance Win32_PnPSignedDriver | Where-Object { $_.DeviceName -match 'NVIDIA|RTX|GeForce' -or $_.Manufacturer -match 'NVIDIA' } | Sort-Object DriverDate -Descending | Select-Object -First 1
    $appVersion = (Get-Item -LiteralPath $appExe).VersionInfo.ProductVersion
    if ($driver -and $appWindow -and $cplPackage -and $cplWindow) {
        Write-Host 'NVID completed successfully after UI launch recovery.' -ForegroundColor Green
        [pscustomobject]@{
            DriverDevice = $driver.DeviceName
            DriverVersion = $driver.DriverVersion
            NvidiaAppVersion = $appVersion
            NvidiaAppWindow = $appWindow.MainWindowTitle
            ControlPanelPackage = $cplPackage.PackageFullName
            ControlPanelWindow = $cplWindow.MainWindowTitle
            RecoveredFrom = $message
        } | Format-List | Out-Host
        return $true
    }
    return $false
}

